"""Replay: no improvement replacing <=5 blocks of Tandon's K4a terminal.
Source: arXiv:2608.30273, Definition 4, Appendix A.3.2, equations 163-165.
Only this fixed 500-dimensional block representation is tested.
Python standard library only; no network access or external input required.
"""
from itertools import combinations, product
from math import prod
from collections import defaultdict
from time import monotonic

LABELS = "BNADOHV"
SEP = dict(B="OHV", N="ADOHV", A="NDH", D="NAV", O="BN", H="BNA", V="BND")
PROFILE = [12651555102711866584006925012965893561076969596025225905818339799, 3066132745665704601020173586804414424611769880543231510544034510, 4664412231532807578550047842170656906931895714626194718133859805, 5561607824514622663538712910059154540700557990699908637174352708, 0, 911561283323995002333709184151818987697897558779375600768623640, 911561283323995002333709184151818987697897558779375600768623640]
INCUMBENT = 'BBBB BNVB BAHB BDVB BHNB BHDB BVAB NBBV NNVH NAVH NDHH NHNH NHAH NVDV ABBV ANHH AAVH ADHH AHAH AVNH AVDH DBBH DNVV DAVV DDHV DHNV DHAV DVDV HAHD HBBA HNVD HDVD HAVN HDHN HHAN HHNN HHND HHDD HVDN HVAD VNVN VBBN VBBD VDVA VNVA VAHA VVAA VHDA VVNA'.split()
EXPECTED = 33964672918117456943408517573718333225317390754651100605971152590324909277046876400440353958428359262989621520394737276681196655776758386330470832773308559159990317076102131413374061066595834823529274560988950698158729501949866486079791784996498585401881281

def separate(a, b):
    return any(y in SEP[x] for x, y in zip(a, b))

def weight(w):
    return prod(PROFILE[LABELS.index(c)] for c in w)

def main():
    if len(INCUMBENT) != len(set(INCUMBENT)) or len(INCUMBENT) != 49:
        raise ValueError("Wrong incumbent size or duplicate block")
    if not all(separate(a,b) for a,b in combinations(INCUMBENT,2)):
        raise ValueError("Incumbent blocks are not separated")
    if sum(map(weight,INCUMBENT)) != EXPECTED:
        raise ValueError("The published cardinality did not reproduce")
    # Zero-weight blocks cannot increase the cardinality and may be omitted.
    alphabet = [c for c,n in zip(LABELS,PROFILE) if n]
    outside = ["".join(w) for w in product(alphabet,repeat=4)
               if "".join(w) not in INCUMBENT]
    groups = defaultdict(list)
    for w in outside:
        blockers = tuple(i for i,r in enumerate(INCUMBENT) if not separate(w,r))
        if len(blockers) <= 5:
            groups[blockers].append(w)
    relevant = [w for group in groups.values() for w in group]
    weights = {w:weight(w) for w in relevant + INCUMBENT}
    conflicts = {w:set() for w in relevant}
    for a,b in combinations(relevant,2):
        if not separate(a,b):
            conflicts[a].add(b)
            conflicts[b].add(a)

    def can_exceed(remaining, needed):
        if needed < 0:
            return True
        if sum(weights[w] for w in remaining) <= needed:
            return False
        w,*rest = remaining
        return (can_exceed([u for u in rest if u not in conflicts[w]], needed-weights[w])
                or can_exceed(rest,needed))

    began = monotonic()
    for r in range(6):
        checked = 0
        for deleted in combinations(range(49),r):
            allowed = [w for k in range(r+1) for key in combinations(deleted,k)
                       for w in groups.get(key,())]
            cost = sum(weights[INCUMBENT[i]] for i in deleted)
            allowed.sort(key=weights.__getitem__,reverse=True)
            if can_exceed(allowed,cost):
                raise AssertionError((deleted,allowed))
            checked += 1
        print({"removed_blocks":r,"completed_deletion_sets":checked,
               "improvement_exists":False},flush=True)
    print({"seconds":monotonic()-began},flush=True)

